fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    // If there are 0 or 1 elements, no delimiters need to be inserted.
    if n <= 1 {
        return numbers;
    }

    // Pre-allocate the needed capacity: 2*n - 1
    let mut result = Vec::with_capacity(2 * n - 1);

    // Consume the original vector, inserting a delimiter before each element
    // after the first.
    let mut iter = numbers.into_iter();
    // We know there is at least one element.
    if let Some(first) = iter.next() {
        result.push(first);
        for num in iter {
            result.push(delimiter);
            result.push(num);
        }
    }

    result
}

